<template><div class="top-progress" :class="{visible}" :style="{transform:`scaleX(${progress/100})`}"/></template>
<script setup>import{onBeforeUnmount,onMounted,ref}from'vue';const progress=ref(0),visible=ref(false);let active=0,timer,hideTimer;function start(){active++;visible.value=true;progress.value=Math.max(progress.value,12);clearInterval(timer);timer=setInterval(()=>{if(progress.value<88)progress.value+=Math.max(.4,(90-progress.value)*.035)},180)}function done(){active=Math.max(0,active-1);if(active)return;clearInterval(timer);progress.value=100;clearTimeout(hideTimer);hideTimer=setTimeout(()=>{visible.value=false;progress.value=0},260)}onMounted(()=>{window.addEventListener('attendance:request-start',start);window.addEventListener('attendance:request-end',done)});onBeforeUnmount(()=>{window.removeEventListener('attendance:request-start',start);window.removeEventListener('attendance:request-end',done);clearInterval(timer);clearTimeout(hideTimer)})</script>
<style scoped>.top-progress{position:fixed;z-index:9999;left:0;top:0;width:100%;height:2px;opacity:0;transform-origin:left;background:linear-gradient(90deg,var(--accent),#70d8ff);box-shadow:0 0 12px rgba(var(--accent-rgb),.55);transition:transform .2s ease,opacity .2s}.top-progress.visible{opacity:1}</style>
